// Optional physical fixture; never part of npm test. All generated bytes are
// written sequentially, synced, and hashed. No sparse padding or giant strings.
import {open,statfs,mkdir,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
const directory=path.resolve(process.argv[2] || 'test-results/large-mlir');
const hexMiB=Number(process.argv[3] || 2560);
if(!Number.isSafeInteger(hexMiB) || hexMiB<1)throw new Error('Expected a positive integer number of MiB.');
await mkdir(directory,{recursive:true});
const disk=await statfs(directory);
if(disk.bavail*disk.bsize<hexMiB*1024*1024*3)throw new Error('Insufficient free space for source and verified exports.');
const name=`weights-${hexMiB}MiB.mlir`,filename=path.join(directory,name),elements=hexMiB*1024*1024/2,type=`tensor<${elements}xi8>`;
const head=`"func.func"() <{sym_name = "large_custom", function_type = (i1, i32) -> i32}> ({
^entry(%condition: i1, %input: i32):
  %weights = "company.weights"() {value = dense<`;
const tail=`> : ${type}} : () -> ${type}
  "cf.cond_br"(%condition)[^left, ^right] <{operandSegmentSizes = array<i32: 1, 0, 0>}> : (i1) -> ()
^left:
  %left = "company.left"(%input, %weights) : (i32, ${type}) -> i32
  "cf.br"(%left)[^join] : (i32) -> ()
^right:
  %right = "company.right"(%input, %weights) : (i32, ${type}) -> i32
  "cf.br"(%right)[^join] : (i32) -> ()
^join(%joined: i32):
  "cf.br"(%joined)[^loop] : (i32) -> ()
^loop(%iteration: i32):
  %next = "company.step"(%iteration) {mode = "loop"} : (i32) -> i32
  "cf.cond_br"(%condition, %next, %next)[^loop, ^exit] <{operandSegmentSizes = array<i32: 1, 1, 1>}> : (i1, i32, i32) -> ()
^exit(%answer: i32):
  "func.return"(%answer) : (i32) -> ()
}) : () -> ()\n`;
const plan={task_id:'mlir-large-20261025',created:new Date().toISOString(),purpose:'Verify local multi-GB MLIR loading, structural patterns, exact weight export and reopen',directory,outputs:[name,'small-same-structure.mlir','node-export.mlir','fixture.json','node-report.json','browser*.png'],cleanup_condition:'Keep source, one verified export, and audit evidence; future cleanup requires explicit scope and current verification.',producer:'scripts/large-mlir-fixture.mjs',hexMiB};
const planFile=await open(path.join(directory,'plan.json'),'wx');await planFile.writeFile(JSON.stringify(plan,null,2));await planFile.sync();await planFile.close();
const events=await open(path.join(directory,'events.jsonl'),'ax');
const event=async e=>{await events.writeFile(JSON.stringify({timestamp:new Date().toISOString(),...e})+'\n');await events.sync();};
await event({operation_id:'generate',event:'create_intent',kind:'temporary',path:filename,purpose:plan.purpose,producer:plan.producer,inputs:{hexMiB},cleanup_condition:plan.cleanup_condition});
const file=await open(filename,'wx'),hash=createHash('sha256'),payload=createHash('sha256');
const write=async bytes=>{await file.writeFile(bytes);hash.update(bytes);};
try {
    await write(head+'"0x');payload.update('"0x');
    const chunk=Buffer.from('5A'.repeat(512*1024));
    for(let i=0;i<hexMiB;i++){await write(chunk);payload.update(chunk);}
    await write('"'+tail);payload.update('"');await file.sync();
} finally {await file.close();}
const small=path.join(directory,'small-same-structure.mlir');
await writeFile(small,head+'1'+tail,{flag:'wx'});
const result={file:filename,bytes:Buffer.byteLength(head+'"0x"'+tail)+hexMiB*1024*1024,sha256:hash.digest('hex'),payloadSha256:payload.digest('hex'),payloadBytes:hexMiB*1024*1024+4,type,small};
await writeFile(path.join(directory,'fixture.json'),JSON.stringify(result,null,2),{flag:'wx'});
await event({operation_id:'generate',event:'created',path:filename,...result});await events.close();
console.log(JSON.stringify(result));
